@Test
public void testAllowNullWithNullableAnnotation() {
    Schema withNullable = ReflectData.AllowNull.get().getSchema(AllowNullWithNullable.class);
    Assert.assertEquals("Should produce a nullable double", nullableSchema(double.class), withNullable.getField("aDouble").schema());
    Schema nullableDoubleOrLong = Schema.createUnion(Arrays.asList(Schema.create(Schema.Type.NULL), Schema.create(Schema.Type.DOUBLE), Schema.create(Schema.Type.LONG)));
    Assert.assertEquals("Should add null to a non-null union", nullableDoubleOrLong, withNullable.getField("doubleOrLong").schema());
    Assert.assertEquals("Should add null to a non-null union", nullableDoubleOrLong, withNullable.getField("doubleOrLongOrNull1").schema());
    Schema doubleOrLongOrNull = Schema.createUnion(Arrays.asList(Schema.create(Schema.Type.DOUBLE), Schema.create(Schema.Type.LONG), Schema.create(Schema.Type.NULL)));
    Assert.assertEquals("Should add null to a non-null union", doubleOrLongOrNull, withNullable.getField("doubleOrLongOrNull2").schema());
    Assert.assertEquals("Should add null to a non-null union", doubleOrLongOrNull, withNullable.getField("doubleOrLongOrNull3").schema());
}

@Test
@SuppressWarnings("unchecked")
public void testWeakSchemaCaching() throws Exception {
    int numSchemas = 1000000;
    for (int i = 0; i < numSchemas; i++) {
        // Create schema
        Schema schema = Schema.createRecord("schema", null, null, false);
        schema.setFields(Collections.<Schema.Field>emptyList());
        ReflectData.get().getRecordState(new Object(), schema);
    }
    // Reflect the number of schemas currently in the cache
    ReflectData.ClassAccessorData classData = ReflectData.ACCESSOR_CACHE.get(Object.class);
    // Not guaranteed, but seems to be reliable enough
    System.gc();
    assertThat("ReflectData cache should release references", classData.bySchema.size(), lessThan(numSchemas));
}

